      "fr": "<p>Dans un épisode légendaire des débuts de Run BTS ! (le Silmido Special), les garçons se sont rendus au XGame Resort, dans les montagnes d'Inje, Gangwon-do, pour affronter leur peur du saut à l'élastique. L'épisode est resté célèbre pour l'hésitation larmoyante de J-Hope et le saut sans peur, tout sourire, de Jungkook.</p><p>Loin du centre de Séoul, la tour de saut du complexe attire encore des ARMY venus revivre les décomptes hurlés des membres avant de sauter à leur tour.</p>",
      "en": "<p>In a legendary early episode of Run BTS! (Episode 9), the boys went to the X-Game Resort in Inje, Gangwon-do, to face their fears by jumping off Korea’s highest bungee platform, which stands at 63 meters. The episode is famous for the unique challenge where members had to guess a song title while in the air, as well as J-Hope's extreme nervousness contrasting with Jungkook's fearless attitude.</p><p>For ARMYs, walking up to this massive 63-meter-high leaning tower brings back hilarious and touching memories of the members jumping into the night sky over the Naerincheon Stream. It is a true test of courage, exactly like the boys experienced!</p>"
