    "id": 212,
    "name": "[CLOSED] LINE Store & BT21 Cafe — Itaewon",
    "group": "BTS",
    "member": "All",
    "country": "South Korea",
    "city": "Seoul",
    "category": "Cafe",
    "year": "2019",
    "episode": "",
    "episodeLink": "https://starsofheavens.com/2019/04/20/line-store-and-bt21-cafe-itaewon-branch-how-to-go-and-what-to-expect/",
