    "address": "55 Jahamun-ro 7-gil, Jongno-gu, Seoul, South Korea",
    "addedAt": 1789076510530,
    "tweetUrl": "https://x.com/bts_twt/status/1086536853778423808?s=46",
    "instagramUrl": "",
    "facebookUrl": "",
