    "name": "Danyang Hanil Cement Quarry",
    "category": "MV Location",
    "address": "Maewa-ro, Maepo-eup, Danyang-gun, Chungcheongbuk-do, South Korea",
    "group": "BTS",
    "addedAt": 1789132587200,
    "tweetUrl": "https://x.com/choi_bts2/status/1151472113372368896",
    "ytId": "9DwzBICPhdM",
    "pinterestUrls": [],
